import json,os,time,numpy as np
from scipy.stats import qmc
from gri_bench.api import load_instance,Experiment
P='/work/output/design.json'; names=['theta_a','relative_leak','ec50_mg_dl','hill_n','tau_min','theta_L']
base={'mode':'responsive','parameters':dict(zip(names,[.0002,1.5,200.,2.,10.,1.]))}
lo=np.array([.00015,.65,100.,.8,2.,.5]); hi=np.array([.0012,3.0,400.,6.,20.,2.5]); logs=np.array([1,0,1,0,1,1],bool)
def dec(x):
 z=lo+(hi-lo)*x; z[logs]=np.exp(np.log(lo[logs])+x[logs]*(np.log(hi[logs])-np.log(lo[logs])))
 return {'mode':'responsive','parameters':dict(zip(names,map(float,z)))}
def save(d):
 with open(P+'.tmp','w') as f:json.dump(d,f,separators=(',',':'))
 os.replace(P+'.tmp',P)
def val(m):return m['mean_tir']-100*max(0,m['max_trajectory_tbr70']-4)-300*max(0,m['max_trajectory_tbr54']-1)-max(0,50-m['minimum_glucose'])
e=Experiment(load_instance()); rec=[]
for d in [base]+[dec(x) for x in qmc.LatinHypercube(6,seed=88).random(56)]:
 m=e.evaluate(d); r=(val(m),m['mean_tir'],m['max_trajectory_tbr70'],m['max_trajectory_tbr54'],m['minimum_glucose'],d);rec.append(r)
rec.sort(key=lambda r:r[0],reverse=True)
for r in rec[:10]:print(r)
if rec[0][0]>0:save(rec[0][-1])
json.dump(rec,open('/work/output/search_records.json','w'))
